/** Validity in hours as issued (issued_at → valid_until), for the bullets. */
export function validityHours(doc: Pick<QuoteDoc, "issuedAt" | "validUntil">): number {
  if (!doc.issuedAt || !doc.validUntil) return 24;
  return Math.round((doc.validUntil.getTime() - doc.issuedAt.getTime()) / 3_600_000);
}

